export function getArticleBySlug(slug: string): JournalArticle | undefined {
  return JOURNAL_ARTICLES.find((a) => a.slug === slug)
}

export function getArticlesByCategory(categorySlug: string): JournalArticle[] {
  return JOURNAL_ARTICLES.filter((a) => a.category === categorySlug)
}

export function getArticlesByTag(tagSlug: string): JournalArticle[] {
  return JOURNAL_ARTICLES.filter((a) => a.tags.includes(tagSlug))
}

export function getFeaturedArticles(): JournalArticle[] {
  return JOURNAL_ARTICLES.filter((a) => a.featured)
}

export function getTrendingArticles(): JournalArticle[] {
  return JOURNAL_ARTICLES.filter((a) => a.trending)
}

export function getPopularArticles(): JournalArticle[] {
  return JOURNAL_ARTICLES.filter((a) => a.popular)
}

export function searchArticles(query: string): JournalArticle[] {
  const q = query.toLowerCase()
  return JOURNAL_ARTICLES.filter(
    (a) =>
      a.title.toLowerCase().includes(q) ||
      a.excerpt.toLowerCase().includes(q) ||
      a.tags.some((t) => t.toLowerCase().includes(q)) ||
      a.category.toLowerCase().includes(q)
  )
}

export function getRelatedArticles(article: JournalArticle, limit = 4): JournalArticle[] {
  return JOURNAL_ARTICLES.filter(
    (a) =>
      a.id !== article.id &&
      (a.category === article.category || a.tags.some((t) => article.tags.includes(t)))
  ).slice(0, limit)
}
